<?php
namespace Sellio\Connector;
defined( 'ABSPATH' ) || exit;
final class Queue {
	const GROUP = 'sellio-connector';
	public static function init() { add_action( 'woocommerce_new_order', array( __CLASS__, 'created' ) ); add_action( 'woocommerce_order_status_changed', array( __CLASS__, 'updated' ) ); add_action( 'woocommerce_order_payment_status_changed', array( __CLASS__, 'updated' ) ); add_action( 'sellio_connector_process', array( __CLASS__, 'process' ) ); add_action( 'sellio_connector_recover', array( __CLASS__, 'recover' ) ); add_action( 'sellio_connector_import', array( __CLASS__, 'import_batch' ) ); }
	public static function created( $id ) { self::enqueue( $id, 'order.created' ); }
	public static function updated( $id ) { self::enqueue( $id, 'order.updated' ); }
	public static function enqueue( $id, $type ) { if ( ! Settings::configured() || ! Settings::all()['automatic'] ) { return; } $order = wc_get_order( $id ); if ( ! $order || $order->get_status() === 'checkout-draft' ) { return; } Outbox::create( $order, $type ); self::schedule(); }
	public static function schedule() { if ( function_exists( 'as_enqueue_async_action' ) ) { as_enqueue_async_action( 'sellio_connector_process', array(), self::GROUP ); } }
	public static function process() { foreach ( Outbox::due() as $id ) { if ( ! Outbox::lock( $id ) ) { continue; } $row = Outbox::get( $id ); $result = Client::send( $row ); if ( $result['ok'] ) { Outbox::update( $id, array( 'status' => 'sent', 'attempts' => $row->attempts + 1, 'last_error' => null ) ); $s = Settings::all(); $s['last_success_at'] = gmdate( 'c' ); $s['last_error'] = ''; update_option( Settings::OPTION, $s, false ); continue; } $attempts = $row->attempts + 1; if ( ! $result['retry'] || $attempts >= 8 ) { Outbox::update( $id, array( 'status' => 'failed', 'attempts' => $attempts, 'last_error' => sanitize_text_field( $result['error'] ) ) ); } else { $delay = ! empty( $result['retry_after'] ) ? min( 3600, $result['retry_after'] ) : min( 3600, ( 30 * ( 2 ** ( $attempts - 1 ) ) ) + wp_rand( 0, 30 ) ); Outbox::update( $id, array( 'status' => 'pending', 'attempts' => $attempts, 'next_attempt' => gmdate( 'Y-m-d H:i:s', time() + $delay ), 'last_error' => sanitize_text_field( $result['error'] ) ) ); } $s = Settings::all(); $s['last_error'] = sanitize_text_field( $result['error'] ); update_option( Settings::OPTION, $s, false ); } }
	public static function recover() { self::schedule(); }
	public static function retry_failed() { global $wpdb; $wpdb->query( "UPDATE " . Outbox::table() . " SET status='pending',next_attempt=NULL WHERE status='failed'" ); self::schedule(); }
	public static function start_import() { $from = gmdate( 'Y-m-d H:i:s', strtotime( '-30 days' ) ); $r = wc_get_orders( array( 'limit' => 1, 'paginate' => true, 'date_created' => '>=' . $from ) ); update_option( 'sellio_connector_import', array( 'from' => $from, 'page' => 1, 'total' => (int) $r->total, 'done' => 0 ), false ); self::schedule_import( 1 ); return (int) $r->total; }
	private static function schedule_import( $page ) { if ( function_exists( 'as_enqueue_async_action' ) ) { as_enqueue_async_action( 'sellio_connector_import', array( $page ), self::GROUP ); } }
	public static function import_batch( $page = 1 ) { $s = get_option( 'sellio_connector_import', array() ); if ( empty( $s['from'] ) || (int) $s['page'] !== (int) $page || ! Settings::configured() ) { return; } $r = wc_get_orders( array( 'limit' => 50, 'page' => (int) $page, 'paginate' => true, 'date_created' => '>=' . $s['from'], 'orderby' => 'date', 'order' => 'ASC' ) ); foreach ( $r->orders as $o ) { if ( 'checkout-draft' !== $o->get_status() ) { Outbox::create( $o, 'order.snapshot' ); } } $s['done'] += count( $r->orders ); $s['page'] = (int) $page + 1; update_option( 'sellio_connector_import', $s, false ); self::schedule(); if ( (int) $page < (int) $r->max_num_pages ) { self::schedule_import( $s['page'] ); } }
}
